129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    protected Set<Pet> getPetsInternal() {
134	        if (this.pets == null) {
135	            this.pets = new HashSet<>();
136	        }
137	        return this.pets;
138	    }
139	
140	    protected void setPetsInternal(Set<Pet> pets) {
141	        this.pets = pets;
142	    }
143	
144	    public List<Pet> getPets() {
145	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
146	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
147	        return Collections.unmodifiableList(sortedPets);
148	    }
149	
150	    public void setPets(List<Pet> pets) {
151	        this.pets = new HashSet<>(pets);
152	    }
153	
154	    public void addPet(Pet pet) {
155	        getPetsInternal().add(pet);
156	        pet.setOwner(this);
157	    }
158	
159	    /**
160	     * Return the Pet with the given name, or null if none found for this Owner.
161	     *
162	     * @param name to test
163	     * @return true if pet name is already in use
164	     */
165	    public Pet getPet(String name) {
166	        return getPet(name, false);
167	    }
168	
169	    /**
170	     * Return the Pet with the given name, or null if none found for this Owner.
171	     *
172	     * @param name to test
173	     * @return true if pet name is already in use
174	     */
175	    public Pet getPet(String name, boolean ignoreNew) {
176	        name = name.toLowerCase();
177	        for (Pet pet : getPetsInternal()) {
178	            if (!ignoreNew || !pet.isNew()) {
179	                String compName = pet.getName();
180	                compName = compName.toLowerCase();
181	                if (compName.equals(name)) {
182	                    return pet;
183	                }
184	            }
185	        }
186	        return null;
187	    }
188	
189	    public Pet getPet(Integer petId) {
190	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
191	    }
192	
193	    @Override
194	    public String toString() {
195	        return new ToStringCreator(this)
196	
197	            .append("id", this.getId())
198	            .append("new", this.isNew())
199	            .append("lastName", this.getLastName())
200	            .append("firstName", this.getFirstName())
201	            .append("address", this.address)
202	            .append("city", this.city)
203	            .append("telephone", this.telephone)
204	            .append("email", this.email)
205	            .toString();
206	    }
207	}
