3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Step of {@code POST /api/owners} that runs after {@link RequireOwnerFields} has normalized
11	 * the telephone to E.164 form. Rejects the create with 409 when that E.164 telephone is
12	 * already used by any existing owner, comparing each stored telephone by its E.164 value so
13	 * differing input formats for the same number still count as duplicates.
14	 */
15	public class RequireUniqueTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = normalize(request.getTelephone());
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(normalize(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(request.getTelephone());
23	            }
24	        }
25	    }
26	
27	    private static String normalize(String telephone) {
28	        String e164 = TelephoneE164.toE164(telephone);
29	        return e164 != null ? e164 : (telephone == null ? "" : telephone);
30	    }
31	}
