6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3
11	 * is the upper-cased first three letters of city, LAST3 the upper-cased first three letters of
12	 * lastName and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
13	 * owners already in that city.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String city3 = prefix3(owner.getCity());
19	        String last3 = prefix3(owner.getLastName());
20	        String city = normalize(owner.getCity());
21	        int sequence = 1;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (city.equals(normalize(existing.getCity()))) {
24	                sequence++;
25	            }
26	        }
27	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
28	    }
29	
30	    /** Upper-cased first three letters of {@code value}. */
31	    private static String prefix3(String value) {
32	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
33	    }
34	
35	    /** Trim, collapse internal whitespace runs to a single space, and lower-case for comparison. */
36	    private static String normalize(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
41	    }
42	}
