2	
3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * Normalizes telephone numbers to E.164 form.
7	 *
8	 * <p>Rules: strip spaces, dashes and brackets; keep a leading '+' and its country code when
9	 * present; otherwise assume country code '+61' and drop a single leading '0' from the national
10	 * digits. The result is '+' followed by 8 to 15 digits, so '0412 345 678' becomes
11	 * '+61412345678' and '+64 21 123 456' becomes '+6421123456'.
12	 */
13	public final class TelephoneE164 {
14	
15	    private TelephoneE164() {
16	    }
17	
18	    /**
19	     * Converts to E.164, throwing {@link InvalidTelephoneException} when the input cannot form a
20	     * valid E.164 number.
21	     */
22	    public static String normalize(String input) throws InvalidTelephoneException {
23	        String e164 = toE164(input);
24	        if (e164 == null) {
25	            throw new InvalidTelephoneException(input);
26	        }
27	        return e164;
28	    }
29	
30	    /**
31	     * Best-effort conversion to E.164; returns {@code null} when the input cannot form a valid
32	     * E.164 number.
33	     */
34	    public static String toE164(String input) {
35	        if (input == null) {
36	            return null;
37	        }
38	        String cleaned = input.replaceAll("[\\s\\-()]", "");
39	        boolean hasPlus = cleaned.startsWith("+");
40	        String digits = hasPlus ? cleaned.substring(1) : cleaned;
41	        if (digits.isEmpty() || !digits.chars().allMatch(c -> c >= '0' && c <= '9')) {
42	            return null;
43	        }
44	        String e164;
45	        if (hasPlus) {
46	            e164 = digits;
47	        }
48	        else {
49	            if (digits.startsWith("0")) {
50	                digits = digits.substring(1);
51	            }
52	            e164 = "61" + digits;
53	        }
54	        if (e164.length() < 8 || e164.length() > 15) {
55	            return null;
56	        }
57	        return "+" + e164;
58	    }
59	}
